// The model is told to return bare HTML but wraps it in a fence often enough
// that stripping one is far cheaper than a retry.
const job = $('Merge Score').first().json;

let html = String($json.text ?? $json.output ?? $json.response ?? '').trim();
html = html
  .replace(/^```(?:html)?[ \t]*\r?\n?/i, '')
  .replace(/\r?\n?```$/, '')
  .trim();

// Drop anything the model said before the document itself.
const docStart = html.search(/<(!doctype|html|body|h1|div)\b/i);
if (docStart > 0) html = html.slice(docStart).trim();

if (!/<html/i.test(html)) {
  html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${job.title || 'Resume'}</title></head><body>${html}</body></html>`;
}

if (html.length < 400) {
  throw new Error(`Generated resume for "${job.title}" is only ${html.length} chars - refusing to upload it.`);
}

return [{ json: { ...job, resumeHtml: html } }];

// Drive v3 converts an upload into a native Google Doc only when the metadata
// part declares the target mimeType, and metadata + content in one request
// means a multipart/related body. Building the body here keeps the HTTP node
// to a single raw send.
const job = $('Merge Score').first().json;
const config = $('Config').first().json;
const html = $json.resumeHtml;

const boundary = `n8n_${Math.random().toString(36).slice(2)}${Date.now().toString(36)}`;

const safe = (value) =>
  String(value ?? '')
    .replace(/[\\/:*?"<>|\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const docName = [safe(job.company) || 'Unknown Company', safe(job.title) || 'Role']
  .join(' - ')
  .slice(0, 120);

const metadata = {
  name: `Resume - ${docName}`,
  mimeType: 'application/vnd.google-apps.document',
};

const folderId = String(config.driveFolderId ?? '').trim();
if (folderId && !folderId.startsWith('PUT_')) metadata.parents = [folderId];

const body = [
  `--${boundary}`,
  'Content-Type: application/json; charset=UTF-8',
  '',
  JSON.stringify(metadata),
  `--${boundary}`,
  'Content-Type: text/html; charset=UTF-8',
  '',
  html,
  `--${boundary}--`,
  '',
].join('\r\n');

return [{ json: { ...job, docName: metadata.name, uploadBoundary: boundary, uploadBody: body } }];

// Keys must match the "Applications" header row exactly - the Sheets node is
// on auto-map, so a renamed key silently creates a new column.
const job = $('Build Drive Upload').first().json;
const doc = $json ?? {};
const docUrl = doc.webViewLink || (doc.id ? `https://docs.google.com/document/d/${doc.id}/edit` : '');

return [
  {
    json: {
      'Date': new Date().toISOString().slice(0, 10),
      'Job ID': job.jobId,
      'Title': job.title,
      'Company': job.company,
      'Location': job.location,
      'Workplace': job.workplaceType,
      'Salary': job.salary,
      'Score': job.score,
      'Verdict': job.verdict,
      'Match Reasons': job.matchReasons,
      'Gaps': job.gaps,
      'Resume Doc': docUrl,
      'Job URL': job.url,
      'Apply URL': job.applyUrl,
      'Status': 'Resume ready',
    },
  },
];

// Skipped jobs are logged too: they are what tells you your threshold or your
// search queries are wrong, and they keep the dedupe set from re-scoring them.
const job = $json;

return [
  {
    json: {
      'Date': new Date().toISOString().slice(0, 10),
      'Job ID': job.jobId,
      'Title': job.title,
      'Company': job.company,
      'Location': job.location,
      'Score': job.score,
      'Verdict': job.verdict,
      'Reason': job.dealBreakerHit ? `Deal-breaker: ${job.gaps}` : job.gaps || job.matchReasons,
      'Job URL': job.url,
      'Status': 'Skipped',
    },
  },
];

// The loop node's "done" output replays every item that was fed back into it,
// which is exactly the two log-row shapes - so the run summary needs no state.
const rows = $input.all().map((item) => item.json ?? {});
const applied = rows.filter((row) => row.Status === 'Resume ready');
const skipped = rows.filter((row) => row.Status === 'Skipped');

const byScore = [...applied].sort((a, b) => Number(b.Score) - Number(a.Score));

const escape = (value) =>
  String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const list = byScore
  .map(
    (row) =>
      `<li><strong>${escape(row.Score)}</strong> - ${escape(row.Title)} at ${escape(row.Company)} (${escape(row.Location)})<br>` +
      `<a href="${escape(row['Resume Doc'])}">Tailored resume</a> &middot; <a href="${escape(row['Job URL'])}">Posting</a></li>`,
  )
  .join('\n');

const html = `<p>Scored <strong>${rows.length}</strong> new postings.</p>
<p><strong>${applied.length}</strong> cleared the threshold and have a tailored resume waiting. <strong>${skipped.length}</strong> were skipped.</p>
${list ? `<ul>\n${list}\n</ul>` : '<p>Nothing cleared the threshold this run.</p>'}`;

return [
  {
    json: {
      scored: rows.length,
      resumesGenerated: applied.length,
      skipped: skipped.length,
      topScore: byScore.length ? Number(byScore[0].Score) : 0,
      subject: `${applied.length} tailored resume${applied.length === 1 ? '' : 's'} ready (${rows.length} jobs scored)`,
      html,
    },
  },
];
